    color.a *= mix(v_outlineColor.a, v_color.a, innerAlpha);

    if (color.a < 0.005)   // matches 0/255 and 1/255
    {
        discard;
    }

    out_FragColor = czm_gammaCorrect(color);
    czm_writeLogDepth();
